from lib import *
S = SS('x103')
steps = [
    step("AuthenticationManager 与各种失败(BCrypt strength 12,用户:alice 正常、bob 禁用、carol 锁定、dave 凭据过期)。AuthenticationConfiguration 给出的 AuthenticationManager 是 ProviderManager,里面只有一个 DaoAuthenticationProvider。authenticate 的结果:alice/pw 成功,发布 AuthenticationSuccessEvent;alice/wrong 抛 BadCredentialsException: Bad credentials,发布 AuthenticationFailureBadCredentialsEvent,用时 286 ms;不存在的用户 nobody 同样抛 BadCredentialsException: Bad credentials,事件也是 BadCredentials,用时 283 ms——和密码错的响应无法区分,耗时也几乎一样(没有因为用户不存在而更快);bob(禁用)抛 DisabledException: User is disabled;carol(锁定)抛 LockedException: User account is locked;dave(凭据过期)抛 CredentialsExpiredException: User credentials have expired,各有对应的 Failure 事件;bob 用错误密码也是 DisabledException——账号状态是在校验密码之前检查的,所以这几种异常会透露「这个用户存在」。", t=tl(S(1)), mark=lidx(S(1), 'authenticate(nobody, pw)', 'authenticate(bob, wrong)', 'authenticate(bob, pw)'), done=lidx(S(1), 'AuthenticationManager = ProviderManager', 'authenticate(alice, pw)', 'authenticate(alice, wrong)', 'authenticate(carol, pw)', 'authenticate(dave, pw)'), b=bars([['密码错的 authenticate 用时(ms)', 286, '286'], ['用户不存在的 authenticate 用时(ms)', 283, '283'], ['被禁用用户的 authenticate 用时(ms)', 290, '290'], ['provider 个数', 1, '1']], 290, mark=[0, 1, 2], done=[3]), kv=KV([['密码错 / 用户不存在', '都是 BadCredentialsException: Bad credentials,耗时相近'], ['禁用 / 锁定 / 过期', 'DisabledException / LockedException / CredentialsExpiredException'], ['bob 用错误密码', '也是 DisabledException:账号状态先于密码检查'], ['事件', '每种结果对应一个 AuthenticationFailure…Event']], ['bob 用错误密码'])),
    step("认证成功之后返回的 Authentication。传入的是 UsernamePasswordAuthenticationToken.unauthenticated(\"alice\", \"pw\"):authenticated=false,credentials=pw。返回的是另一个对象(和传入的不是同一个):类型还是 UsernamePasswordAuthenticationToken,authenticated=true,principal 是 org.springframework.security.core.userdetails.User,credentials=null(密码已经被擦掉),authorities 是 [ROLE_USER, FactorGrantedAuthority [authority=FACTOR_PASSWORD, issuedAt=…]]——Spring Security 7 在认证成功时多给了一条 FACTOR_PASSWORD 的权限,记录这次是靠「密码」这一因子认证的。", t=tl(S(2)), mark=lidx(S(2), '传入的对象'), done=[], b=bars([['传入对象的 authenticated(1=true)', 0, 'false'], ['返回对象的 authenticated', 1, 'true'], ['返回对象的 credentials 是否还在(1=还在)', 0, 'null'], ['authorities 里的条数(ROLE_USER 加 FACTOR_PASSWORD)', 2, '2']], 2, mark=[0, 2], done=[1, 3]), kv=KV([['传入', 'unauthenticated,credentials = pw'], ['返回', '新的对象,authenticated = true,credentials = null'], ['principal', 'UserDetails(User)'], ['Spring Security 7', 'authorities 里多了 FACTOR_PASSWORD']], ['返回'])),
    step("hideUserNotFoundExceptions 关掉之后:DaoAuthenticationProvider.setHideUserNotFoundExceptions(false),authenticate(nobody, pw) 抛的是 UsernameNotFoundException: user not found,而不是默认的 BadCredentialsException: Bad credentials——默认把「用户不存在」伪装成「密码错」,是为了不让攻击者枚举用户名;关掉它就暴露了用户是否存在。", t=tl(S(3)), mark=lidx(S(3), 'hideUserNotFoundExceptions=false'), done=[], b=bars([['默认下用户不存在抛的异常是否等同于密码错(1=是)', 1, '是'], ['hideUserNotFoundExceptions=false 时是否等同(1=是)', 0, '否:UsernameNotFoundException']], 1, done=[0], mark=[1]), kv=KV([['默认', '用户不存在 → BadCredentialsException'], ['关掉 hide', '用户不存在 → UsernameNotFoundException'], ['代价', '攻击者可以枚举用户名'], ['建议', '保持默认']], ['默认'])),
    step("SecurityContext 在线程之间。默认策略 ThreadLocalSecurityContextHolderStrategy:alice 登录 GET /who,请求线程看到 alice;提交到普通线程池里的任务看到的是 null;new Thread 里也是 null;包了 DelegatingSecurityContextExecutorService 的线程池里是 alice。换成 spring.security.strategy=MODE_INHERITABLETHREADLOCAL:alice 的请求里,线程池和新建线程都看到 alice——但接着用 erin 登录再请求一次:请求线程是 erin,新建线程是 erin,而普通线程池里仍然是 alice——线程池的线程是第一次请求时创建的,继承了当时的上下文,之后一直是旧的。只有 DelegatingSecurityContextExecutorService 每次都是对的(alice 对 alice,erin 对 erin)。", t=tl(S(4)), mark=lidx(S(4), '用 erin 登录 GET /who → 请求线程=erin;普通线程池=alice'), done=lidx(S(4), '用 alice 登录', 'MODE_INHERITABLETHREADLOCAL'), b=bars([['默认策略:普通线程池看到的用户(0=null)', 0, 'null'], ['INHERITABLE:erin 的请求里普通线程池看到的是谁(1=旧用户 alice)', 1, 'alice(旧的)'], ['DelegatingSecurityContextExecutorService:erin 的请求里看到的是谁(1=erin)', 1, 'erin']], 1, mark=[0, 1], done=[2]), kv=KV([['ThreadLocal(默认)', '新线程、普通线程池里都是 null'], ['INHERITABLETHREADLOCAL', '线程创建时继承,线程池里会一直是旧用户'], ['DelegatingSecurityContextExecutorService', '每次提交任务时带上提交者的上下文'], ['建议', '异步任务用 Delegating… 包装的执行器']], ['INHERITABLETHREADLOCAL'])),
]
A = mkartx('x103', 103, 'Spring,Security,认证,AuthenticationManager,SecurityContext,真实验证,动画演示',
    '实测 Spring Security 7 的认证流程:ProviderManager 里默认只有一个 DaoAuthenticationProvider;密码错与用户不存在都是 BadCredentialsException,耗时相近;禁用、锁定、凭据过期有各自的异常和事件;成功返回的是新对象,凭据被擦掉并多了 FACTOR_PASSWORD 权限;SecurityContext 默认只在请求线程里有,INHERITABLETHREADLOCAL 会让线程池里一直是第一次请求的用户。',
    '用户名不存在和密码错怎么区分不开?禁用的用户用错误密码登录会得到什么异常?认证成功后密码还在吗?异步线程里为什么拿不到当前用户?这篇在 Spring Boot 4.0.8、Spring Security 7 上直接调用 AuthenticationManager 逐个实测。',
    [('286 vs 283 ms', '密码错与用户不存在的 authenticate 用时:几乎一样,异常也都是 BadCredentialsException'), ('FACTOR_PASSWORD', 'Spring Security 7 认证成功后 authorities 里多出的一条,记录认证因子'), ('null / alice / erin', '普通线程池里看到的用户:默认是 null;INHERITABLETHREADLOCAL 下 erin 的请求里仍是 alice')],
    [('各种失败', '<p>密码错与用户不存在对外一样;禁用、锁定、凭据过期各有异常,且先于密码检查。</p>'),
     ('成功的返回值', '<p>新的 Authentication,credentials 被擦掉,多了 FACTOR_PASSWORD 权限。</p>'),
     ('隐藏用户不存在', '<p>hideUserNotFoundExceptions=false 会抛 UsernameNotFoundException,暴露用户是否存在。</p>'),
     ('线程之间', '<p>默认 ThreadLocal 不带到其他线程;INHERITABLE 会让线程池里一直是旧用户;用 DelegatingSecurityContextExecutorService。</p>')],
    steps,
    [ENV_X + '(Spring Security 7,BCrypt strength 12)。InMemoryUserDetailsManager 里五个用户(alice、erin 正常,bob 禁用,carol 锁定,dave 凭据过期),密码都是 pw;authenticate 的耗时包含 BCrypt 校验,首次调用较慢;SecurityContext 的线程实验是启动两次应用,第二次加 -Dspring.security.strategy=MODE_INHERITABLETHREADLOCAL;线程池只有 1 个线程',
     '没有验证:自定义 AuthenticationProvider 与多个 provider 的尝试顺序、parent 链;RememberMe、预认证等其他 Authentication 类型;FactorGrantedAuthority 在 Spring Security 7 多因子认证里的具体用法;ReactiveSecurityContextHolder;密码错误次数过多后的锁定(见第 114 篇);hideUserNotFoundExceptions=false 时用户不存在与存在时的耗时差异(只测了异常类型)'],
    '认证流程')
